using System.Reflection;
using System.Text;

namespace LabVIEWMcp.Infra;

/// <summary>
/// The VI Server names a generated Property or Invoke Node may use, from four embedded tables:
/// LabVIEW's catalogue (<c>vi-server-properties.tsv</c>, <c>vi-server-methods.tsv</c>), its
/// complete class list (<c>vi-server-classes.tsv</c>), and the names WORKING AIXML uses
/// (<c>vi-server-aixml-names.tsv</c>, generated by <c>scripts/harvest_aixml_vi_server_names.py</c>
/// from NI's own exports and our shipped helpers).
///
/// WHY TWO NAME SOURCES. The catalogue is keyed by display name and holds what its collector VIs
/// happened to contain. Measured 2026-09-09, half the names in our own working helpers are absent
/// from it (<c>Ctrl Val.Set</c> is the call, <c>Set Control Value [Variant]</c> the row), and
/// 2026-10-10 over NI's 792 cached exports 207 property fields and 71 method targets miss it -
/// <c>{LV.Project}</c> is missing as a class. A name in EITHER source is known; a check against
/// the catalogue alone would accuse working code, which is worse than no check.
///
/// A missing resource leaves the vocabulary empty, and an empty vocabulary judges nothing: every
/// question then answers "known", so a binary-only install without the tables is never refused.
/// </summary>
internal static class ViServerVocabulary
{
    private sealed record Tables(
        Dictionary<string, HashSet<string>> Properties,
        Dictionary<string, HashSet<string>> Methods,
        HashSet<string> Classes);

    private static readonly Lazy<Tables> Data = new(Build);

    /// <summary>Whether the tables loaded at all; with no data every name counts as known.</summary>
    internal static bool Loaded => Data.Value.Properties.Count > 0;

    /// <summary>
    /// Whether <paramref name="cls"/> (<c>{LV.VI}</c>) is one of LabVIEW's VI Server classes.
    /// Only <c>{LV.*}</c> is judged: GenClass, Visa, ActiveX and .NET refnums are other families
    /// whose names this repository has no list of.
    /// </summary>
    internal static bool IsKnownClass(string cls)
    {
        if (!Loaded || !cls.StartsWith("{LV.", StringComparison.Ordinal)) return true;
        return Data.Value.Classes.Contains(cls[4..^1]) || Data.Value.Properties.ContainsKey(cls)
               || Data.Value.Methods.ContainsKey(cls);
    }

    /// <summary>The known property names of a class, or null when nothing is known about it.</summary>
    internal static IReadOnlySet<string>? PropertiesOf(string cls) =>
        Data.Value.Properties.TryGetValue(cls, out var names) ? names : null;

    /// <summary>The known method names of a class, or null when nothing is known about it.</summary>
    internal static IReadOnlySet<string>? MethodsOf(string cls) =>
        Data.Value.Methods.TryGetValue(cls, out var names) ? names : null;

    /// <summary>
    /// A method name with its two working spellings folded together: the catalogue lists
    /// <c>Print VI To HTML</c> and <c>Print.VI To Printer</c> for the same shape, and LabVIEW
    /// accepts either on import (docs/vi-server-reference.md, "Method names have two spellings").
    /// </summary>
    internal static string FoldMethod(string name) =>
        name.Replace('.', ' ').Replace("  ", " ", StringComparison.Ordinal).Trim();

    private static Tables Build()
    {
        var properties = new Dictionary<string, HashSet<string>>(StringComparer.Ordinal);
        var methods = new Dictionary<string, HashSet<string>>(StringComparer.Ordinal);
        var classes = new HashSet<string>(StringComparer.Ordinal);

        static void Add(Dictionary<string, HashSet<string>> into, string cls, string name)
        {
            if (!into.TryGetValue(cls, out var set))
                into[cls] = set = new HashSet<string>(StringComparer.Ordinal);
            set.Add(name);
        }

        foreach (var row in Rows("vi-server-properties.tsv"))
            if (row.Length >= 2) Add(properties, row[0], row[1]);
        foreach (var row in Rows("vi-server-methods.tsv"))
            if (row.Length >= 2) Add(methods, row[0], FoldMethod(row[1]));
        foreach (var row in Rows("vi-server-aixml-names.tsv"))
        {
            if (row.Length < 3) continue;
            if (row[1] == "property") Add(properties, row[0], row[2]);
            else if (row[1] == "method") Add(methods, row[0], FoldMethod(row[2]));
        }
        foreach (var row in Rows("vi-server-classes.tsv"))
            if (row.Length >= 1 && row[0].Length > 0) classes.Add(row[0]);

        return new Tables(properties, methods, classes);
    }

    /// <summary>The data rows of an embedded TSV, header skipped; none when it is not embedded.</summary>
    private static IEnumerable<string[]> Rows(string resource)
    {
        using var stream = Assembly.GetExecutingAssembly().GetManifestResourceStream(resource);
        if (stream is null) yield break;
        using var reader = new StreamReader(stream, Encoding.UTF8);
        var header = true;
        while (reader.ReadLine() is { } line)
        {
            if (header) { header = false; continue; }
            if (line.Length == 0) continue;
            yield return line.Split('\t');
        }
    }
}
